                need = int(math.ceil(shortage - EPS))
                take = min(cover, need)
                if take <= 0:
                    continue
                local_stock[sub['sub']] = sub_onhand - take * sub['ratio']
                shortage -= take
                if shortage <= EPS:
                    break

            if shortage > EPS:
                return None

