def calculate_required_resources(root, qty, stock, children, parts, bom_by_parent, routing_by_parent):
    required = {'leaves': defaultdict(float), 'workcenters': defaultdict(float)}
    if qty <= 0:
        return required

    _, topo = topo_for_part(root, children)
    gross = defaultdict(float)
    gross[root] = float(qty)

    for part in topo:
        demand = gross.get(part, 0.0)
        if demand <= EPS:
