        if part in bom_by_parent:
            on_hand = stock.get(part, 0.0)
            consume = min(on_hand, demand)
            shortage = demand - consume
            if shortage <= EPS:
                continue

            batch = parts[part]['batch']
            build_qty = ceil_to_batch(shortage, batch)

            for route in routing_by_parent.get(part, []):
                required['workcenters'][route['wc']] += route['setup'] + build_qty * route['run']

            for b in bom_by_parent[part]:
                base = b['qty_per'] * build_qty
                running = math.ceil(base * (1.0 + b['scrap_rate_pct'] / 100.0) - EPS)
                child_req = running + b['setup_scrap_qty']
                gross[b['child']] += child_req
        else:
            required['leaves'][part] += demand

